package main

import "fmt"

// Any type with these methods satisfies Shape implicitly: no "implements".
type Shape interface {
	Name() string
	Area() int
}

type Rectangle struct{ Width, Height int }
type Triangle struct{ Base, Height int }

func (r Rectangle) Name() string { return "Rectangle" }
func (r Rectangle) Area() int    { return r.Width * r.Height }

func (t Triangle) Name() string { return "Triangle" }
func (t Triangle) Area() int    { return t.Base * t.Height / 2 }

func main() {
	shapes := []Shape{Rectangle{3, 4}, Triangle{10, 3}}
	for _, s := range shapes {
		fmt.Printf("%s: %d\n", s.Name(), s.Area())
	}
}

